// CS 313 automatic check. The same check runs on GitHub after every push.
//
//   npm run check
//
// It rebuilds your database from scratch (migrations, undo, migrations again,
// seed data), starts a second copy of your API on port 3099, calls the Hub
// Contract endpoints, and reads your Git history. Each line of the scorecard
// shows the rubric criterion it belongs to.
//
// DO NOT EDIT THIS FILE, OR ANYTHING IN .github/. Changing the check is treated
// as an academic-integrity matter, and GitHub keeps the history of every file.
// On GitHub, the workflow downloads the official copy of this file from the class
// template before it runs, so a changed copy in your repository is never used.
//
// CHECK_WEEK says which weeks' lines are checked. The instructor raises it in the
// class template each week; every student's next push uses the new number.
const CHECK_WEEK = Number(process.env.CHECK_WEEK) || 16;
const { spawn, spawnSync } = require('child_process');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const CHECK_PORT = Number(process.env.CHECK_PORT) || 3099;
const BASE = `http://localhost:${CHECK_PORT}/api/v1`;
const IN_CI = process.env.GITHUB_ACTIONS === 'true';
const from = (week) => CHECK_WEEK >= week;

const results = [];       // { criterion, label, status: 'pass' | 'fail' | 'warn' | 'skip', detail }
function record(criterion, label, status, detail = '') {
  results.push({ criterion, label, status, detail });
}
const pass = (c, l, d) => record(c, l, 'pass', d);
const fail = (c, l, d) => record(c, l, 'fail', d);
const warn = (c, l, d) => record(c, l, 'warn', d);
const skip = (c, l, d) => record(c, l, 'skip', d);

function run(command) {
  const out = spawnSync(command, { cwd: ROOT, shell: true, encoding: 'utf8', env: process.env });
  return { ok: out.status === 0, text: `${out.stdout || ''}${out.stderr || ''}`.trim() };
}
function lastLines(text, n = 3) {
  return text.split('\n').map((l) => l.trim()).filter(Boolean).slice(-n).join(' | ');
}

/* ------------------------------------------------------------------ A, B: the repository */
function checkRepository() {
  const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));
  const pkgProblems = [];
  if (pkg.name === 'your-game-api') pkgProblems.push('"name" is still your-game-api');
  if (/CHANGE_ME/.test(pkg.description || '')) pkgProblems.push('"description" still says CHANGE_ME');
  if (/CHANGE_ME/.test(pkg.author || '')) pkgProblems.push('"author" still says CHANGE_ME');
  if (pkgProblems.length) fail('A', 'package.json describes your game', pkgProblems.join('; '));
  else pass('A', 'package.json describes your game', `${pkg.name}, by ${pkg.author}`);

  const readme = fs.existsSync(path.join(ROOT, 'README.md')) ? fs.readFileSync(path.join(ROOT, 'README.md'), 'utf8') : '';
  if (!readme) fail('A', 'README.md is filled in', 'README.md is missing');
  else if (/\[Your Game Title\]|\[Your full name\]|CHANGE_ME/.test(readme)) fail('A', 'README.md is filled in', 'it still contains [Your Game Title], [Your full name] or CHANGE_ME');
  else pass('A', 'README.md is filled in');

  const tracked = run('git ls-files');
  if (!tracked.ok) {
    skip('B', '.env is not in the repository', 'this folder is not a Git repository');
    return;
  }
  const files = tracked.text.split('\n');
  const envFiles = files.filter((f) => /(^|\/)\.env$/.test(f));
  if (envFiles.length) fail('B', '.env is not in the repository', `remove it: git rm --cached ${envFiles[0]}, then change your password`);
  else pass('B', '.env is not in the repository');
  if (files.some((f) => f.startsWith('node_modules/'))) fail('B', 'node_modules is not in the repository', 'remove it: git rm -r --cached node_modules');
  else pass('B', 'node_modules is not in the repository');

  const example = fs.existsSync(path.join(ROOT, '.env.example')) ? fs.readFileSync(path.join(ROOT, '.env.example'), 'utf8') : '';
  const keys = ['NODE_ENV', 'PORT', 'DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD', 'HUB_API_KEY'];
  if (from(12)) keys.push('JWT_SECRET');
  if (from(14)) keys.push('CORS_ORIGINS');
  const missingKeys = keys.filter((k) => !new RegExp(`^${k}=`, 'm').test(example));
  if (missingKeys.length) fail('B', '.env.example lists every key', `missing: ${missingKeys.join(', ')}`);
  else pass('B', '.env.example lists every key');
}

/* ------------------------------------------------------------------ B: the official workflow */
// SHA-256 of every official version of .github/workflows/check.yml (line endings ignored).
const OFFICIAL_WORKFLOWS = {
  '3924b1e05452b99a4e59f2f1d28cf2d6b401721b5ddac38e5246f8016454637c': 'Week 12 kit',
};
function checkWorkflow() {
  const file = path.join(ROOT, '.github', 'workflows', 'check.yml');
  if (!fs.existsSync(file)) {
    fail('B', 'The workflow is the official Week 12 version', '.github/workflows/check.yml is missing: copy it from the Week 12 kit');
    return;
  }
  const text = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
  const hash = crypto.createHash('sha256').update(text).digest('hex');
  if (OFFICIAL_WORKFLOWS[hash]) pass('B', 'The workflow is the official Week 12 version', OFFICIAL_WORKFLOWS[hash]);
  else fail('B', 'The workflow is the official Week 12 version', 'it differs from the kit: copy .github/workflows/check.yml from the Week 12 kit again, unchanged');
}

/* ------------------------------------------------------------------ G: Git history */
function checkHistory() {
  const log = run('git log --format=%H%x09%an%x09%cn%x09%ce%x09%P%x09%s');
  if (!log.ok) {
    skip('G', 'Commits were made with Git on your own computer', 'no Git history found');
    return;
  }
  const commits = log.text.split('\n').filter(Boolean).map((line) => {
    const [hash, author, committer, committerEmail, parents, ...subject] = line.split('\t');
    return { hash, author, committer, committerEmail, parents: parents ? parents.split(' ') : [], subject: subject.join('\t') };
  });
  // The first commit of a repository made from the template is created by GitHub. It is not yours and not counted.
  const own = commits.filter((c) => c.parents.length > 0);
  const madeOnWebsite = own.filter((c) => (c.committerEmail === 'noreply@github.com' || c.committer === 'GitHub')
    && !/^Merge pull request #\d+/.test(c.subject));

  if (madeOnWebsite.length) {
    const list = madeOnWebsite.slice(0, 5).map((c) => `${c.hash.slice(0, 7)} "${c.subject}"`).join('; ');
    fail('G', 'Commits were made with Git on your own computer', `${madeOnWebsite.length} made on the GitHub website (upload or web editor): ${list}`);
  } else {
    pass('G', 'Commits were made with Git on your own computer', `${own.length} commits checked`);
  }

  if (own.length >= 5) pass('G', 'At least 5 commits of your own', `${own.length} commits`);
  else fail('G', 'At least 5 commits of your own', `${own.length} so far: commit after each step of the lab`);

  const typed = own.filter((c) => /^(feat|fix|chore|docs|test|refactor|style)(\(.+\))?: \S/.test(c.subject));
  if (own.length && typed.length / own.length >= 0.8) pass('G', 'Commit messages start with a type', `${typed.length} of ${own.length}`);
  else warn('G', 'Commit messages start with a type', `${typed.length} of ${own.length}, for example "feat(db): add users table"`);
}

/* ------------------------------------------------------------------ C, D: the database */
function buildDatabase() {
  const steps = [
    ['C', 'Every migration runs on an empty database', 'npx sequelize-cli db:migrate'],
    ['C', 'Every migration can be undone', 'npx sequelize-cli db:migrate:undo:all'],
    ['C', 'Every migration runs again after the undo', 'npx sequelize-cli db:migrate'],
    ['D', 'The seed data loads', 'npx sequelize-cli db:seed:all'],
  ];
  // Start from nothing, the same way a classmate or the instructor would.
  const wipe = run('node scripts/db-wipe.js');
  if (!wipe.ok) {
    fail('C', 'The database can be reached', lastLines(wipe.text));
    return false;
  }
  for (const [criterion, label, command] of steps) {
    const out = run(command);
    if (!out.ok) {
      fail(criterion, label, lastLines(out.text));
      return false;
    }
    pass(criterion, label);
  }
  return true;
}

async function checkDatabase() {
  const { QueryTypes } = require('sequelize');
  const { sequelize } = require(path.join(ROOT, 'src', 'models'));
  const q = (sql) => sequelize.query(sql, { type: QueryTypes.SELECT });
  try {
    const tables = (await q(`SELECT tablename AS name FROM pg_tables WHERE schemaname = 'public'
      AND tablename NOT IN ('SequelizeMeta', 'SequelizeData') ORDER BY tablename`)).map((t) => t.name);
    if (tables.length >= 4) pass('C', 'At least four tables exist', tables.join(', '));
    else fail('C', 'At least four tables exist', `found ${tables.length}: write one migration for each table in your ERD`);

    const userCols = (await q(`SELECT column_name AS c FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'users'`)).map((r) => r.c);
    const needed = ['user_id', 'school_id', 'full_name', 'email', 'role'];
    const missingCols = needed.filter((c) => !userCols.includes(c));
    if (!userCols.length) fail('C', 'A users table, as in Design Change Notice 01', 'there is no table named users');
    else if (missingCols.length) fail('C', 'A users table, as in Design Change Notice 01', `missing columns: ${missingCols.join(', ')}`);
    else pass('C', 'A users table, as in Design Change Notice 01');

    // The rejoin rule: some table has UNIQUE on two columns, one of them user_id.
    const seatRules = await q(`SELECT c.conname AS name, c.conrelid::regclass::text AS tbl,
        array_agg(a.attname::text ORDER BY a.attname) AS cols
      FROM pg_constraint c JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
      WHERE c.contype = 'u' AND c.connamespace = 'public'::regnamespace
      GROUP BY c.conname, c.conrelid HAVING count(*) = 2`);
    const seat = seatRules.find((r) => r.cols.includes('user_id'));
    if (seat) pass('C', 'One seat per account per game (UNIQUE with user_id)', `${seat.name} on ${seat.tbl}`);
    else fail('C', 'One seat per account per game (UNIQUE with user_id)', 'add a UNIQUE constraint on your seat table: the game column and user_id');

    const counts = [];
    for (const t of tables) {
      const [{ n }] = await q(`SELECT COUNT(*)::int AS n FROM "${t}"`);
      counts.push([t, n]);
    }
    const empty = counts.filter(([, n]) => n === 0).map(([t]) => t);
    if (!tables.length) skip('D', 'Every table has seed rows', 'no tables');
    else if (empty.length) fail('D', 'Every table has seed rows', `empty: ${empty.join(', ')}`);
    else pass('D', 'Every table has seed rows', counts.map(([t, n]) => `${t} ${n}`).join(', '));

    const before = counts.reduce((s, [, n]) => s + n, 0);
    const again = run('npx sequelize-cli db:seed:all');
    let after = 0;
    for (const t of tables) after += (await q(`SELECT COUNT(*)::int AS n FROM "${t}"`))[0].n;
    if (again.ok && after === before) pass('D', 'Seeding a second time changes nothing');
    else fail('D', 'Seeding a second time changes nothing', again.ok ? `rows went from ${before} to ${after}` : lastLines(again.text));
  } catch (error) {
    fail('C', 'The database can be read', error.message);
  }
}

/* ------------------------------------------------------------------ E, F: the API */
// The API closes idle connections after a few seconds. A request that lands on a
// connection at the moment it closes fails with "other side closed": try once more.
async function fetchRetry(url, options) {
  try {
    return await fetch(url, options);
  } catch (error) {
    await new Promise((r) => setTimeout(r, 300));
    return fetch(url, options);
  }
}

async function call(url, headers = {}) {
  const res = await fetchRetry(url, { headers });
  let body = null;
  const text = await res.text();
  try { body = JSON.parse(text); } catch { body = text; }
  return { status: res.status, body };
}
const isErrorShape = (b) => b && typeof b === 'object' && b.error && typeof b.error.code === 'string' && typeof b.error.message === 'string';
const isIso = (v) => typeof v === 'string' && !Number.isNaN(Date.parse(v));

async function startApi() {
  const api = spawn(process.execPath, ['src/server.js'], { cwd: ROOT, env: { ...process.env, PORT: String(CHECK_PORT) } });
  let log = '';
  api.stdout.on('data', (d) => { log += d; });
  api.stderr.on('data', (d) => { log += d; });
  for (let i = 0; i < 40; i += 1) {
    await new Promise((r) => setTimeout(r, 500));
    if (api.exitCode !== null) break;
    try { await fetch(`${BASE}/health`); return { api, log: () => log }; } catch { /* not up yet */ }
  }
  api.kill();
  throw new Error(lastLines(log) || 'the API did not start within 20 seconds');
}

async function checkApi() {
  const health = await call(`${BASE}/health`);
  if (health.status === 200 && health.body && health.body.database === 'up') pass('E', 'GET /health answers 200, database "up"');
  else fail('E', 'GET /health answers 200, database "up"', `answered ${health.status}`);

  const info = await call(`${BASE}/game-info`);
  const g = info.body || {};
  const problems = [];
  ['slug', 'name', 'team', 'developer', 'description', 'version'].forEach((k) => {
    if (typeof g[k] !== 'string' || !g[k].trim()) problems.push(`${k} is missing`);
    else if (/CHANGE_ME/.test(g[k])) problems.push(`${k} still says CHANGE_ME`);
  });
  if (typeof g.slug === 'string' && !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(g.slug)) problems.push('slug must be lower case with hyphens');
  if (!Number.isInteger(g.min_players) || !Number.isInteger(g.max_players) || g.min_players > g.max_players) problems.push('min_players and max_players must be whole numbers, min ≤ max');
  const owner = process.env.GITHUB_REPOSITORY_OWNER;
  if (owner && typeof g.developer === 'string' && g.developer.toLowerCase() !== owner.toLowerCase()) problems.push(`developer is "${g.developer}" but this repository belongs to "${owner}"`);
  if (info.status === 200 && !problems.length) pass('E', 'GET /game-info describes your build', `${g.slug} by ${g.developer}`);
  else fail('E', 'GET /game-info describes your build', info.status !== 200 ? `answered ${info.status}` : problems.join('; '));

  const nope = await call(`${BASE}/this-route-does-not-exist`);
  if (nope.status === 404 && isErrorShape(nope.body)) pass('E', 'An unknown address answers 404 in the error format');
  else fail('E', 'An unknown address answers 404 in the error format', `answered ${nope.status}`);

  const key = { 'X-Hub-Key': process.env.HUB_API_KEY };
  const noKey = await call(`${BASE}/results`);
  if (noKey.status === 401 && isErrorShape(noKey.body)) pass('F', 'GET /results without the Hub key answers 401');
  else fail('F', 'GET /results without the Hub key answers 401', `answered ${noKey.status}: results must never be public`);

  const res = await call(`${BASE}/results`, key);
  const b = res.body || {};
  const shape = [];
  if (res.status !== 200) shape.push(`answered ${res.status}`);
  if (b.game !== g.slug) shape.push('"game" must equal your slug');
  if (!isIso(b.generated_at)) shape.push('"generated_at" must be a date and time');
  if (!Array.isArray(b.results)) shape.push('"results" must be a list');
  const games = Array.isArray(b.results) ? b.results : [];
  games.forEach((game, i) => {
    const where = `game ${i + 1}`;
    if (!/^[1-9][0-9]{5}$/.test(String(game.session_code))) shape.push(`${where}: session_code must be six digits`);
    if (!isIso(game.ended_at)) shape.push(`${where}: ended_at must be a date and time`);
    if (!Array.isArray(game.players) || !game.players.length) shape.push(`${where}: players must be a non-empty list`);
    (game.players || []).forEach((p) => {
      if (typeof p.school_id !== 'string' || typeof p.nickname !== 'string' || typeof p.score !== 'number' || typeof p.completed !== 'boolean') {
        shape.push(`${where}: each player needs school_id, nickname, score (a number) and completed (true or false)`);
      }
    });
    if (!Array.isArray(game.podium)) shape.push(`${where}: podium must be a list`);
    else if (game.podium.some((p) => !(p.rank >= 1 && p.rank <= 3))) shape.push(`${where}: podium ranks must be 1 to 3`);
  });
  const unique = [...new Set(shape)];
  if (!unique.length) pass('F', 'GET /results with the key answers in the contract format', `${games.length} finished game(s)`);
  else fail('F', 'GET /results with the key answers in the contract format', unique.slice(0, 3).join('; '));

  const full = games.find((game) => (game.players || []).filter((p) => p.completed).length >= 3);
  if (full) pass('F', 'The seed data has a finished game with 3 or more completed players', `game ${full.session_code}: podium ${full.podium.map((p) => `${p.rank}. ${p.nickname}`).join(', ')}`);
  else fail('F', 'The seed data has a finished game with 3 or more completed players', 'seed one game that has ended, with at least three players who completed it');

  const later = await call(`${BASE}/results?since=2999-01-01T00:00:00Z`, key);
  if (later.status === 200 && Array.isArray(later.body.results) && later.body.results.length === 0) pass('F', '?since= returns only games that ended after it');
  else fail('F', '?since= returns only games that ended after it', `a date in the year 2999 should return an empty list (answered ${later.status})`);

  const bad = await call(`${BASE}/results?since=not-a-date`, key);
  if (bad.status === 400 && isErrorShape(bad.body)) pass('F', 'A wrong ?since= answers 400');
  else fail('F', 'A wrong ?since= answers 400', `answered ${bad.status}`);
}

/* ------------------------------------------------------------------ H: accounts (Week 12) */
async function send(method, url, body, headers = {}) {
  const res = await fetchRetry(url, {
    method,
    headers: { ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}), ...headers },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let parsed = null;
  try { parsed = JSON.parse(text); } catch { parsed = text; }
  return { status: res.status, body: parsed, text, headers: res.headers };
}
const CHECK_ID = '2099-9901';
const CHECK_PASSWORD = 'Check-Pass-2026';

async function checkAccounts() {
  const account = { school_id: CHECK_ID, full_name: 'Check Account', email: 'check.account@cs313.test', password: CHECK_PASSWORD };
  const reg = await send('POST', `${BASE}/auth/register`, { ...account, role: 'ADMIN' });
  const leaks = /password|\$2[aby]\$/i.test(reg.text);
  const user = reg.body && reg.body.user ? reg.body.user : reg.body || {};
  if (reg.status === 404) {
    fail('H', 'The /auth endpoints exist', 'POST /api/v1/auth/register answered 404: mount auth.routes.js in src/routes/index.js');
    return;
  }
  if (reg.status !== 201) fail('H', 'POST /auth/register answers 201', `answered ${reg.status}: ${lastLines(reg.text, 1).slice(0, 120)}`);
  else if (leaks) fail('H', 'POST /auth/register answers 201', 'the answer contains the password or its hash: never send either back');
  else pass('H', 'POST /auth/register answers 201, without the password or its hash');
  if (reg.status === 201) {
    if (user.role === 'PLAYER') pass('H', 'A new account is a PLAYER, even when the body asks for ADMIN');
    else fail('H', 'A new account is a PLAYER, even when the body asks for ADMIN', `role came back as ${JSON.stringify(user.role)}: take only the fields that have rules (matchedData)`);
  }

  const again = await send('POST', `${BASE}/auth/register`, { ...account, email: 'check.other@cs313.test' });
  if (again.status === 409 && isErrorShape(again.body)) pass('H', 'Registering a taken school ID answers 409');
  else fail('H', 'Registering a taken school ID answers 409', `answered ${again.status}: map the UNIQUE constraint of school_id in constraint-map.js`);

  const weak = await send('POST', `${BASE}/auth/register`, { school_id: '2099-9902', full_name: 'Weak Password', email: 'weak@cs313.test', password: 'abc' });
  if (weak.status === 400 && isErrorShape(weak.body)) pass('H', 'A weak password answers 400');
  else fail('H', 'A weak password answers 400', `"abc" answered ${weak.status}: add a length rule to password`);

  // The password must be stored as a bcrypt hash, never as itself.
  try {
    const { QueryTypes } = require('sequelize');
    const { sequelize } = require(path.join(ROOT, 'src', 'models'));
    const rows = await sequelize.query('SELECT * FROM users WHERE school_id = :id', { replacements: { id: CHECK_ID }, type: QueryTypes.SELECT });
    const values = rows.length ? Object.values(rows[0]).map((v) => String(v)) : [];
    if (!rows.length) fail('H', 'The password is stored as a bcrypt hash', 'the registered account is not in the users table');
    else if (values.includes(CHECK_PASSWORD)) fail('H', 'The password is stored as a bcrypt hash', 'the password is stored as plain text');
    else if (values.some((v) => /^\$2[aby]\$\d{2}\$.{53}$/.test(v))) pass('H', 'The password is stored as a bcrypt hash');
    else fail('H', 'The password is stored as a bcrypt hash', 'no column holds a bcrypt hash ($2b$10$...)');
  } catch (error) {
    fail('H', 'The password is stored as a bcrypt hash', error.message);
  }

  const wrong = await send('POST', `${BASE}/auth/login`, { school_id: CHECK_ID, password: 'Wrong-Pass-2026' });
  const nobody = await send('POST', `${BASE}/auth/login`, { school_id: '2099-9999', password: 'Wrong-Pass-2026' });
  if (wrong.status === 401 && nobody.status === 401 && isErrorShape(wrong.body) && isErrorShape(nobody.body)) {
    if (wrong.body.error.code === nobody.body.error.code && wrong.body.error.message === nobody.body.error.message) {
      pass('H', 'A wrong password and an unknown school ID get the same 401');
    } else {
      fail('H', 'A wrong password and an unknown school ID get the same 401', 'the two answers differ, so the login form tells strangers which school IDs exist');
    }
  } else {
    fail('H', 'A wrong password and an unknown school ID get the same 401', `answered ${wrong.status} and ${nobody.status}`);
  }

  const ok = await send('POST', `${BASE}/auth/login`, { school_id: CHECK_ID, password: CHECK_PASSWORD });
  const token = ok.body && typeof ok.body.token === 'string' ? ok.body.token : '';
  if (ok.status === 200 && token.split('.').length === 3 && !/password|\$2[aby]\$/i.test(ok.text)) pass('H', 'POST /auth/login answers 200 with a token');
  else fail('H', 'POST /auth/login answers 200 with a token', ok.status !== 200 ? `answered ${ok.status}` : 'the body needs "token" (a JWT) and no password or hash');

  const me = await send('GET', `${BASE}/auth/me`, undefined, { Authorization: `Bearer ${token}` });
  if (me.status === 200 && me.text.includes(CHECK_ID) && !/password|\$2[aby]\$/i.test(me.text)) pass('H', 'GET /auth/me with the token answers 200 with the account');
  else fail('H', 'GET /auth/me with the token answers 200 with the account', `answered ${me.status}`);

  const none = await send('GET', `${BASE}/auth/me`);
  const bent = await send('GET', `${BASE}/auth/me`, undefined, { Authorization: `Bearer ${token.slice(0, -2)}xx` });
  const demo = await send('GET', `${BASE}/auth/me`, undefined, { 'X-Demo-User': '2099-0001' });
  const bad = [['no token', none], ['a changed token', bent], ['the Week 11 X-Demo-User header', demo]]
    .filter(([, r]) => !(r.status === 401 && isErrorShape(r.body))).map(([what, r]) => `${what} answered ${r.status}`);
  if (!bad.length) pass('H', 'No token, a changed token and X-Demo-User all answer 401');
  else fail('H', 'No token, a changed token and X-Demo-User all answer 401', bad.join('; '));
}

/* ------------------------------------------------------------------ I, J: your Postman collection */
function findCollection() {
  const dir = path.join(ROOT, 'postman');
  if (!fs.existsSync(dir)) return { error: 'there is no postman folder' };
  const files = fs.readdirSync(dir).filter((f) => f.endsWith('.json'));
  const collections = files.filter((f) => {
    try { return Boolean(JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')).item); } catch { return false; }
  });
  if (!collections.length) return { error: 'the postman folder has no exported collection (Collection v2.1)' };
  if (collections.length > 1) return { error: `keep ONE collection in postman/, found ${collections.length}: ${collections.join(', ')}` };
  return { file: path.join('postman', collections[0]) };
}

function countRequests(items) {
  return (items || []).reduce((n, it) => n + (it.request ? 1 : countRequests(it.item)), 0);
}

async function checkCollection() {
  const minimum = from(13) ? 45 : 30;
  const found = findCollection();
  if (found.error) {
    fail('I', 'Your Postman collection passes on a fresh database', found.error);
    return null;
  }
  const collection = JSON.parse(fs.readFileSync(path.join(ROOT, found.file), 'utf8'));
  const count = countRequests(collection.item);
  if (count >= minimum) pass('I', `The collection has at least ${minimum} requests`, `${count} in ${found.file}`);
  else fail('I', `The collection has at least ${minimum} requests`, `${count} in ${found.file}: one saved request per case`);

  // Start from the seed data again, exactly as "npm run db:reset" would.
  const reset = run('node scripts/db-wipe.js && npx sequelize-cli db:migrate && npx sequelize-cli db:seed:all');
  if (!reset.ok) {
    fail('I', 'Your Postman collection passes on a fresh database', `db:reset failed: ${lastLines(reset.text)}`);
    return null;
  }
  const startedAt = new Date();
  const report = path.join(ROOT, '.check-newman.json');
  const out = run(`npx --yes newman@6 run "${found.file}" --env-var "baseUrl=${BASE}" --env-var "hubKey=${process.env.HUB_API_KEY}" --reporters cli,json --reporter-json-export "${report}" --timeout-request 10000`);
  let summary = null;
  try { summary = JSON.parse(fs.readFileSync(report, 'utf8')).run; } catch { /* newman did not run */ }
  fs.rmSync(report, { force: true });
  if (!summary) {
    fail('I', 'Your Postman collection passes on a fresh database', lastLines(out.text));
    return null;
  }
  const failures = summary.failures || [];
  const assertions = summary.stats.assertions;
  if (!failures.length && assertions.total > 0) {
    pass('I', 'Your Postman collection passes on a fresh database', `${summary.stats.requests.total} requests, ${assertions.total} tests, 0 failed`);
  } else if (!assertions.total) {
    fail('I', 'Your Postman collection passes on a fresh database', 'no request has a test: add pm.test(...) to every request');
  } else {
    const first = failures.slice(0, 3).map((f) => `"${f.source && f.source.name}": ${f.error && f.error.message}`).join('; ');
    fail('I', 'Your Postman collection passes on a fresh database', `${failures.length} failed. ${first}`);
  }
  return startedAt;
}

async function checkPlayedGame(startedAt) {
  const label = 'Your collection plays a game to the end: /results lists it, with a player who completed it';
  if (!startedAt) {
    fail('J', label, 'the collection did not run');
    return;
  }
  const res = await call(`${BASE}/results?since=${startedAt.toISOString()}`, { 'X-Hub-Key': process.env.HUB_API_KEY });
  const games = res.body && Array.isArray(res.body.results) ? res.body.results : [];
  const played = games.find((g) => (g.players || []).some((p) => p.completed === true));
  if (played) pass('J', label, `game ${played.session_code}: ${played.players.filter((p) => p.completed).length} completed, podium ${(played.podium || []).map((p) => `${p.rank}. ${p.nickname}`).join(', ')}`);
  else if (games.length) fail('J', label, `${games.length} game(s) ended during the run, but nobody completed one: play every question before the host closes the game`);
  else fail('J', label, 'no game ended during the run: start a game, answer, then close it in your collection');
}

/* ------------------------------------------------------------------ K: automated tests (Week 14) */
function checkTests() {
  const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));
  const hasJest = (pkg.devDependencies && pkg.devDependencies.jest) || (pkg.dependencies && pkg.dependencies.jest);
  if (!hasJest || !pkg.scripts || !pkg.scripts.test || /no test specified/.test(pkg.scripts.test)) {
    fail('K', 'npm test runs your Jest tests and every test passes', 'install jest and supertest as devDependencies and set "test" in package.json');
    return;
  }
  const reset = run('node scripts/db-wipe.js && npx sequelize-cli db:migrate && npx sequelize-cli db:seed:all');
  if (!reset.ok) {
    fail('K', 'npm test runs your Jest tests and every test passes', `db:reset failed: ${lastLines(reset.text)}`);
    return;
  }
  const dir = path.join(ROOT, '.check-jest');
  fs.rmSync(dir, { recursive: true, force: true });
  const out = run(`npx jest --ci --runInBand --json --outputFile="${path.join(dir, 'result.json')}" --coverage --coverageReporters=json-summary --coverageDirectory="${dir}"`);
  let result = null;
  let coverage = null;
  try { result = JSON.parse(fs.readFileSync(path.join(dir, 'result.json'), 'utf8')); } catch { /* jest did not finish */ }
  try { coverage = JSON.parse(fs.readFileSync(path.join(dir, 'coverage-summary.json'), 'utf8')).total; } catch { /* no coverage */ }
  fs.rmSync(dir, { recursive: true, force: true });
  if (!result) {
    fail('K', 'npm test runs your Jest tests and every test passes', lastLines(out.text));
    return;
  }
  if (result.success && result.numFailedTests === 0) pass('K', 'npm test runs your Jest tests and every test passes', `${result.numPassedTests} tests in ${result.numTotalTestSuites} files`);
  else fail('K', 'npm test runs your Jest tests and every test passes', `${result.numFailedTests} failed, ${result.numPassedTests} passed`);

  if (result.numTotalTests >= 15) pass('K', 'At least 15 tests', `${result.numTotalTests}`);
  else fail('K', 'At least 15 tests', `${result.numTotalTests} so far`);

  const files = result.testResults.map((t) => fs.readFileSync(t.name || t.testFilePath, 'utf8'));
  const unit = files.some((t) => /jest\.mock\(/.test(t));
  const http = files.some((t) => /supertest/.test(t));
  if (unit && http) pass('K', 'Unit tests (jest.mock) and HTTP tests (supertest) both exist');
  else fail('K', 'Unit tests (jest.mock) and HTTP tests (supertest) both exist', `${unit ? '' : 'no test file uses jest.mock. '}${http ? '' : 'no test file uses supertest.'}`.trim());

  const pct = coverage ? coverage.lines.pct : 0;
  if (pct >= 60) pass('K', 'Your tests run at least 60% of the lines in src', `${pct}%`);
  else fail('K', 'Your tests run at least 60% of the lines in src', coverage ? `${pct}%: test the services, where the rules are` : 'no coverage report');
}

/* ------------------------------------------------------------------ L: CORS (Week 14) */
async function checkCors() {
  const allowed = (process.env.CORS_ORIGINS || '').split(',')[0].trim();
  const preflight = (origin) => fetch(`${BASE}/health`, { method: 'OPTIONS', headers: { Origin: origin, 'Access-Control-Request-Method': 'GET' } });
  const good = await preflight(allowed);
  const evil = await preflight('http://not-allowed.test');
  const goodHeader = good.headers.get('access-control-allow-origin');
  const evilHeader = evil.headers.get('access-control-allow-origin');
  if (goodHeader === allowed) pass('L', 'CORS allows an origin listed in CORS_ORIGINS', allowed);
  else fail('L', 'CORS allows an origin listed in CORS_ORIGINS', `Access-Control-Allow-Origin was ${JSON.stringify(goodHeader)} for ${allowed}`);
  if (!evilHeader) pass('L', 'CORS refuses an origin that is not listed');
  else fail('L', 'CORS refuses an origin that is not listed', `answered Access-Control-Allow-Origin: ${evilHeader}. Never use "*" with logins`);
}

/* ------------------------------------------------------------------ M: API documentation (Week 15) */
async function checkApiDocs() {
  const spec = await call(`${BASE}/openapi.json`);
  const doc = spec.body || {};
  const ops = [];
  Object.entries(doc.paths || {}).forEach(([p, item]) => Object.entries(item || {}).forEach(([verb, op]) => {
    if (['get', 'post', 'put', 'patch', 'delete'].includes(verb)) ops.push({ p, verb, op });
  }));
  if (spec.status === 200 && /^3\./.test(String(doc.openapi)) && doc.info && doc.info.title) pass('M', 'GET /openapi.json answers an OpenAPI 3 document', `${doc.info.title} ${doc.info.version || ''}`.trim());
  else fail('M', 'GET /openapi.json answers an OpenAPI 3 document', spec.status !== 200 ? `answered ${spec.status}` : '"openapi" must start with 3. and "info.title" must be set');
  const undocumented = ops.filter(({ op }) => !op.responses || !Object.keys(op.responses).length || !op.summary);
  if (ops.length >= 15 && !undocumented.length) pass('M', 'At least 15 operations, each with a summary and its responses', `${ops.length} operations`);
  else fail('M', 'At least 15 operations, each with a summary and its responses', ops.length < 15 ? `${ops.length} operations documented` : `${undocumented.length} lack a summary or responses, for example ${undocumented[0].verb.toUpperCase()} ${undocumented[0].p}`);
  const ui = await fetch(`${BASE}/docs/`);
  const html = await ui.text();
  if (ui.status === 200 && /swagger/i.test(html)) pass('M', 'GET /docs shows Swagger UI');
  else fail('M', 'GET /docs shows Swagger UI', `answered ${ui.status}`);
}

/* ------------------------------------------------------------------ N: the live API (Week 15) */
async function checkLive() {
  const readme = fs.existsSync(path.join(ROOT, 'README.md')) ? fs.readFileSync(path.join(ROOT, 'README.md'), 'utf8') : '';
  const m = readme.match(/Live API:\s*(https:\/\/\S+?)\/?\s*$/m);
  if (!m) {
    fail('N', 'The README names your live API', 'add a line such as:  Live API: https://shelf-climb-yourname.onrender.com/api/v1');
    return;
  }
  const live = m[1].replace(/\/$/, '');
  pass('N', 'The README names your live API', live);
  let health = null;
  for (let attempt = 0; attempt < 9 && !health; attempt += 1) {      // a sleeping free service needs up to a minute
    try {
      const res = await fetch(`${live}/health`, { signal: AbortSignal.timeout(15000) });
      if (res.status === 200) health = await res.json();
      else await new Promise((r) => setTimeout(r, 5000));
    } catch { /* still waking up */ }
  }
  if (health && health.database === 'up') pass('N', 'The live API answers /health with the database "up"');
  else fail('N', 'The live API answers /health with the database "up"', health ? `database is ${health.database}` : 'no answer within about 2 minutes: open the Render dashboard and read the logs');
  if (!health) return;
  try {
    const info = await (await fetch(`${live}/game-info`, { signal: AbortSignal.timeout(15000) })).json();
    const owner = process.env.GITHUB_REPOSITORY_OWNER;
    if (!owner || String(info.developer).toLowerCase() === owner.toLowerCase()) pass('N', 'The live API is your build', `developer ${info.developer}`);
    else fail('N', 'The live API is your build', `the live /game-info says developer "${info.developer}"`);
  } catch (error) {
    fail('N', 'The live API is your build', error.message);
  }
}

/* ------------------------------------------------------------------ O: the SE1 portfolio (Week 16) */
async function checkPortfolio(tables) {
  const docs = path.join(ROOT, 'docs');
  const read = (f) => (fs.existsSync(path.join(docs, f)) ? fs.readFileSync(path.join(docs, f), 'utf8') : '');
  const required = ['technical-spec.md', 'data-dictionary.md', 'api-reference.md', 'user-guide.md', 'se2-handoff.md'];
  const missing = required.filter((f) => read(f).trim().length < 200);
  if (!missing.length) pass('O', 'docs/ has the five portfolio documents');
  else fail('O', 'docs/ has the five portfolio documents', `missing or nearly empty: ${missing.join(', ')}`);
  const placeholder = required.filter((f) => /\[Your |CHANGE_ME|TODO/.test(read(f)));
  if (!placeholder.length) pass('O', 'No placeholders are left in docs/');
  else fail('O', 'No placeholders are left in docs/', `still in: ${placeholder.join(', ')}`);
  const dd = read('data-dictionary.md');
  const absent = (tables || []).filter((t) => !new RegExp(`\\b${t}\\b`).test(dd));
  if (dd && !absent.length) pass('O', 'The data dictionary covers every table in the database', `${(tables || []).length} tables`);
  else fail('O', 'The data dictionary covers every table in the database', dd ? `not described: ${absent.join(', ')}` : 'docs/data-dictionary.md is missing');
  const diagramDir = path.join(docs, 'diagrams');
  const images = fs.existsSync(diagramDir) ? fs.readdirSync(diagramDir).filter((f) => /\.(png|jpe?g|svg)$/i.test(f)) : [];
  const needed = ['use-case', 'class', 'sequence', 'activity', 'erd', 'architecture'];
  const absentDiagrams = needed.filter((n) => !images.some((f) => f.toLowerCase().startsWith(n)));
  if (!absentDiagrams.length) pass('O', 'docs/diagrams has the six diagrams', images.join(', '));
  else fail('O', 'docs/diagrams has the six diagrams', `missing: ${absentDiagrams.map((n) => `${n}.png`).join(', ')}`);
}

/* ------------------------------------------------------------------ report */
const NAMES = { A: 'Set-up', B: 'Secrets', C: 'Migrations', D: 'Seed data', E: 'Hub endpoints', F: 'Results', G: 'Git history',
  H: 'Accounts', I: 'Postman', J: 'Gameplay', K: 'Tests', L: 'CORS', M: 'API docs', N: 'Live API', O: 'Portfolio' };
const MARK = { pass: '✔', fail: '✘', warn: '⚠', skip: '–' };

function report() {
  const order = Object.keys(NAMES);
  results.sort((a, b) => order.indexOf(a.criterion) - order.indexOf(b.criterion));
  console.log('\nCS 313 automatic check\n');
  for (const r of results) {
    console.log(`${MARK[r.status]}  ${r.criterion}  ${r.label}${r.detail ? `\n      ${r.detail}` : ''}`);
  }
  const failed = results.filter((r) => r.status === 'fail').length;
  const passed = results.filter((r) => r.status === 'pass').length;
  console.log(`\n${passed} passed, ${failed} failed.${failed ? ' Fix the ✘ lines, commit, and push again.' : ' Everything passed.'}\n`);

  if (process.env.GITHUB_STEP_SUMMARY) {
    const md = [`## CS 313 automatic check (Week ${CHECK_WEEK})`, '',
      failed ? `**${failed} failed**, ${passed} passed. Fix the ✘ lines, commit, and push again.` : `**Everything passed** (${passed} checks).`, '',
      '| | Criterion | Check | Detail |', '|---|---|---|---|',
      ...results.map((r) => `| ${MARK[r.status]} | ${r.criterion} ${NAMES[r.criterion]} | ${r.label} | ${String(r.detail).replace(/\|/g, '/')} |`), ''];
    fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, md.join('\n'));
  }
  return failed;
}

async function listTables() {
  try {
    const { QueryTypes } = require('sequelize');
    const { sequelize } = require(path.join(ROOT, 'src', 'models'));
    const rows = await sequelize.query(`SELECT tablename AS name FROM pg_tables WHERE schemaname = 'public'
      AND tablename NOT IN ('SequelizeMeta', 'SequelizeData')`, { type: QueryTypes.SELECT });
    return rows.map((r) => r.name);
  } catch {
    return [];
  }
}

async function main() {
  if (!IN_CI) console.log('This rebuilds your database from scratch, as a fresh clone would. Your seed data is loaded again at the end.');
  checkRepository();
  if (from(12) && IN_CI) checkWorkflow();
  checkHistory();

  let env;
  try {
    env = require(path.join(ROOT, 'src', 'config', 'env'));
  } catch (error) {
    fail('B', 'The API finds every .env key', error.message);
  }
  if (env) {
    pass('B', 'The API finds every .env key');
    if (buildDatabase()) {
      await checkDatabase();
      if (from(16)) await checkPortfolio(await listTables());
      let started;
      try {
        started = await startApi();
      } catch (error) {
        fail('E', 'The API starts', error.message);
      }
      if (started) {
        pass('E', 'The API starts');
        try {
          await checkApi();
          if (from(12)) await checkAccounts();
          if (from(14)) await checkCors();
          if (from(15)) await checkApiDocs();
          if (from(12)) {
            const startedAt = await checkCollection();
            if (from(13)) await checkPlayedGame(startedAt);
          }
        } catch (error) {
          fail('E', 'The API answers', `${error.message}${error.cause ? ` (${error.cause.message})` : ''} | ${lastLines(started.log(), 2)}`);
        } finally {
          started.api.kill();
        }
      }
    }
  }
  if (from(14) && env) checkTests();
  if (from(15)) await checkLive();
  try { await require(path.join(ROOT, 'src', 'models')).sequelize.close(); } catch { /* never opened */ }
  const failed = report();
  process.exit(failed ? 1 : 0);
}

main().catch((error) => {
  console.error('THE CHECK ITSELF FAILED:', error.message);
  process.exit(1);
});
